// EU cosmetic ingredient reference data.
//
// `IngredientReferenceData` loads the imported EU CosIng annexes (II-VI)
// from assets/data/ingredient_reference.json, generated by
// tool/update_ingredient_data.dart. Re-run that script occasionally to
// refresh it — COSING annexes change several times a year.
//
// The fragrance allergen list below is hand-curated separately: COSING has
// no dedicated "is an allergen" column to derive it from automatically.
//
// `microplastics` in the JSON is a separate, non-COSING import: the "Red
// List" from Beat the Microbead / Plastic Soup Foundation (see
// tool/parse_microplastics_list.dart), current as of 05.01.2022. There is
// no official EU per-substance microplastics list to import (the REACH
// restriction, Regulation 2023/2055, is defined by physical/chemical
// criteria, not a named-substance list) — this NGO list is broader/more
// precautionary than that legal definition (e.g. it includes Dimethicone,
// which is not a solid particle), so it's kept as its own category with
// an explicit caveat rather than folded into the COSING-derived ratings.

import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

class IngredientReferenceData {
  IngredientReferenceData._();

  static Set<String> banned = {};
  static Set<String> restricted = {};
  static Set<String> permitted = {};

  /// Ingredient name -> readable CMR classification (e.g. "krebserregend
  /// Kat. 1B"), for names that have one. Not every banned/restricted name
  /// has an entry.
  static Map<String, String> bannedCmr = {};
  static Map<String, String> restrictedCmr = {};

  /// Banned names whose Annex II entry is actually a *conditional* ban
  /// (e.g. "Petrolatum, except if the full refining history is known and
  /// it can be shown that the substance ... is not a carcinogen") rather
  /// than an unconditional one.
  static Set<String> bannedConditional = {};

  static Set<String> microplastics = {};

  /// Permitted (Annex IV-VI) name -> readable usage condition (e.g. "max.
  /// 7,34 % (Face products with the exception of propellent spray
  /// products)"), for names that have one.
  static Map<String, String> permittedConditions = {};

  static Future<void> load() async {
    final jsonString = await rootBundle.loadString(
      'assets/data/ingredient_reference.json',
    );
    final data = jsonDecode(jsonString) as Map<String, dynamic>;
    banned = Set<String>.from(data['banned'] as List);
    restricted = Set<String>.from(data['restricted'] as List);
    permitted = Set<String>.from(data['permitted'] as List);
    bannedCmr = Map<String, String>.from(
      data['bannedCmr'] as Map? ?? const {},
    );
    restrictedCmr = Map<String, String>.from(
      data['restrictedCmr'] as Map? ?? const {},
    );
    bannedConditional = Set<String>.from(
      data['bannedConditional'] as List? ?? const [],
    );
    microplastics = Set<String>.from(
      data['microplastics'] as List? ?? const [],
    );
    permittedConditions = Map<String, String>.from(
      data['permittedConditions'] as Map? ?? const {},
    );
  }
}

